            return False
        for r in range(c + 1, 3):
            f = M[r][c] / M[c][c]
            M[r] = [M[r][k] - f * M[c][k] for k in range(3)]
    return True
def det_pivot(A):
    M = [[F(x) for x in r] for r in A]
    sign = 1
    for c in range(3):
        p = None
        for r in range(c, 3):
            if M[r][c] != 0:
                p = r
                break
        if p is None:
            return 0
        if p != c:
            M[c], M[p] = M[p], M[c]
            sign = -sign
        for r in range(c + 1, 3):
            f = M[r][c] / M[c][c]
            M[r] = [M[r][k] - f * M[c][k] for k in range(3)]
    return sign * M[0][0] * M[1][1] * M[2][2]
